#include "lanlink/app/options.hpp"
#include <cerrno>
#include <cmath>
#include <cstdlib>
#include <string_view>
namespace lanlink::app { namespace {
Result<std::uint64_t> uintval(std::string_view s, std::string_view f) { if(s.empty()) return Result<std::uint64_t>::failure(std::string(f)+" requires a value"); for(char c:s) if(c<'0'||c>'9') return Result<std::uint64_t>::failure(std::string(f)+" must be an integer"); std::string x(s); char* e=nullptr; errno=0; auto v=std::strtoull(x.c_str(),&e,10); if(errno==ERANGE||e!=x.c_str()+x.size()) return Result<std::uint64_t>::failure(std::string(f)+" must be an integer"); return Result<std::uint64_t>::success((std::uint64_t)v); }
Result<double> dbl(std::string_view s,std::string_view f) { if(s.empty()) return Result<double>::failure(std::string(f)+" requires a value"); std::string x(s); char* e=nullptr; errno=0; double v=std::strtod(x.c_str(),&e); if(errno==ERANGE||e!=x.c_str()+x.size()||!std::isfinite(v)||v<=0) return Result<double>::failure(std::string(f)+" must be positive and finite"); return Result<double>::success(v); }
Result<std::string_view> next(int& i,int n,char* const a[],std::string_view f) { if(i+1>=n) return Result<std::string_view>::failure(std::string(f)+" requires a value"); return Result<std::string_view>::success(a[++i]); }
Result<transport::Endpoint> endpoint(std::string_view s) { auto p=s.rfind(':'); if(p==std::string_view::npos||p==0||p+1>=s.size()||s.find(':')!=p) return Result<transport::Endpoint>::failure("--connect must be HOST:PORT"); auto n=uintval(s.substr(p+1),"--connect port"); if(!n.ok()||n.value()==0||n.value()>65535) return Result<transport::Endpoint>::failure("--connect port must be in 1..65535"); return Result<transport::Endpoint>::success({std::string(s.substr(0,p)),(std::uint16_t)n.value()}); }
}
std::string usage() { return "Usage: lanlink_app --device-id N --peer-id N --listen-port P [options]\n--device-id --peer-id --listen-port --connect --display-id --peer-display-id --remote-side --width --height --help\n"; }
Result<AppOptions> parse_options(int argc,char* const argv[]) { AppOptions o; for(int i=1;i<argc;++i) { std::string_view f=argv[i]?argv[i]:""; if(f=="--help") return Result<AppOptions>::failure(usage()); if(f=="--device-id"||f=="--peer-id"||f=="--listen-port"||f=="--display-id"||f=="--peer-display-id") { auto s=next(i,argc,argv,f); if(!s.ok()) return Result<AppOptions>::failure(s.error()); auto n=uintval(s.value(),f); if(!n.ok()) return Result<AppOptions>::failure(n.error()); if(f=="--device-id")o.device_id=n.value(); else if(f=="--peer-id")o.peer_id=n.value(); else if(f=="--listen-port"){if(!n.value()||n.value()>65535)return Result<AppOptions>::failure("--listen-port must be in 1..65535");o.listen_port=(std::uint16_t)n.value();} else if(f=="--display-id")o.display_id=n.value(); else o.peer_display_id=n.value(); } else if(f=="--connect") { auto s=next(i,argc,argv,f); if(!s.ok())return Result<AppOptions>::failure(s.error()); auto e=endpoint(s.value()); if(!e.ok())return Result<AppOptions>::failure(e.error()); o.connect=e.value(); } else if(f=="--remote-side") { auto s=next(i,argc,argv,f); if(!s.ok())return Result<AppOptions>::failure(s.error()); if(s.value()=="left")o.remote_side=RemoteSide::kLeft; else if(s.value()=="right")o.remote_side=RemoteSide::kRight; else return Result<AppOptions>::failure("--remote-side must be left or right"); } else if(f=="--width"||f=="--height") { auto s=next(i,argc,argv,f); if(!s.ok())return Result<AppOptions>::failure(s.error()); auto d=dbl(s.value(),f); if(!d.ok())return Result<AppOptions>::failure(d.error()); if(f=="--width")o.width=d.value();else o.height=d.value(); } else return Result<AppOptions>::failure("unknown argument: "+std::string(f)); } if(!o.device_id)return Result<AppOptions>::failure("--device-id must be non-zero"); if(!o.peer_id)return Result<AppOptions>::failure("--peer-id must be non-zero"); if(!o.listen_port)return Result<AppOptions>::failure("--listen-port is required and must be non-zero"); return Result<AppOptions>::success(o); }
Uuid128 numeric_id(std::uint64_t v){return {0,v};}
Result<ScreenTopology> make_topology(const AppOptions&o) { if(!o.device_id||!o.peer_id||!o.display_id||!o.peer_display_id)return Result<ScreenTopology>::failure("IDs must be non-zero"); if(!std::isfinite(o.width)||!std::isfinite(o.height)||o.width<=0||o.height<=0)return Result<ScreenTopology>::failure("dimensions must be positive and finite"); auto ld=numeric_id(o.display_id),pd=numeric_id(o.peer_display_id); bool r=o.remote_side==RemoteSide::kRight; Display a{numeric_id(o.device_id),ld,{0,0,o.width,o.height},1.0,Rotation::k0}; Display b{numeric_id(o.peer_id),pd,r?Rect{o.width,0,2*o.width,o.height}:Rect{-o.width,0,0,o.height},1.0,Rotation::k0}; ScreenLink l{ld,r?Edge::kRight:Edge::kLeft,pd,r?Edge::kLeft:Edge::kRight,0,1,1}; ScreenTopology t; auto z=t.set_snapshot(1,{a,b},{l}); if(!z.ok())return Result<ScreenTopology>::failure(z.error()); return Result<ScreenTopology>::success(std::move(t)); }
}
